

export function fmtDate(d) {
  if(!d) return '—';
  try{const dt=new Date(d);return dt.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});}catch{return d;}
}
export function fmtMoney(n,c='AED') { return `${c} ${(+n||0).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:0})}`; }
export function daysUntil(d) {
  if(!d) return 9999;
  const diff = new Date(d) - new Date();
  return Math.ceil(diff/86400000);
}
export function getInitials(name='') { return name.split(' ').slice(0,2).map(w=>w[0]||'').join('').toUpperCase(); }
export const AV_BG = ['#dbeafe','#ede9fe','#d1fae5','#fef3c7','#fee2e2','#fce7f3','#ccfbf1','#ffedd5','#e0e7ff','#ecfccb'];
export const AV_CL = ['#1e40af','#5b21b6','#065f46','#92400e','#991b1b','#9d174d','#134e4a','#c2410c','#3730a3','#3f6212'];
export function getAV(id='') { const i=parseInt(id.replace(/\D/g,''))%10; return {background:AV_BG[i],color:AV_CL[i]}; }
export function expiryBadge(days) {
  if(days<=0) return 'badge-red';
  if(days<=30) return 'badge-red';
  if(days<=60) return 'badge-amber';
  if(days<=90) return 'badge-amber';
  return 'badge-green';
}
export function expiryLabel(days) {
  if(days<0) return 'Expired';
  if(days===0) return 'Today';
  if(days<=30) return `${days}d — URGENT`;
  return `${days} days`;
}
export function today() { return new Date().toISOString().split('T')[0]; }
export function nowId() { return Date.now().toString(36).toUpperCase(); }
export const COMPANY_LOGO='data:image/jpeg;base64,';

export function printProfessionalReport({title, subtitle, columns, rows, footerRow, summaryCards, empById, period}) {
  const today = new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'});
  const ref = 'NP-'+new Date().getFullYear()+'-'+Date.now().toString(36).toUpperCase().slice(-6);

  let tableRows = '';
  rows.forEach((r,ri) => {
    const stripe = ri%2===0 ? '' : 'background:#fafbfc;';
    tableRows += `<tr style="${stripe}">`;
    r.forEach((cell,i) => {
      const align = columns[i]?.align || 'left';
      const bold = columns[i]?.bold ? 'font-weight:700;' : '';
      const color = cell?.color || '';
      const val = cell?.value !== undefined ? cell.value : cell;
      tableRows += `<td style="text-align:${align};${bold}${color?'color:'+color+';':''}">${val}</td>`;
    });
    tableRows += '</tr>';
  });

  let footerHtml = '';
  if(footerRow) {
    footerHtml = '<tfoot><tr style="background:#f1f5f9;font-weight:700;">';
    footerRow.forEach((cell,i) => {
      const align = columns[i]?.align || 'left';
      const val = cell?.value !== undefined ? cell.value : cell;
      const color = cell?.color || '';
      footerHtml += `<td style="text-align:${align};${color?'color:'+color+';':''}">${val}</td>`;
    });
    footerHtml += '</tr></tfoot>';
  }

  let summaryHtml = '';
  if(summaryCards && summaryCards.length > 0) {
    summaryHtml = '<div style="display:flex;gap:12px;margin:20px 0 24px;flex-wrap:wrap;">';
    summaryCards.forEach(c => {
      summaryHtml += `<div style="flex:1;min-width:110px;padding:14px 16px;background:${c.bg||'#f8fafc'};border-radius:6px;border:1px solid #e2e8f0;">
        <div style="font-size:9px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.6px;margin-bottom:5px;">${c.label}</div>
        <div style="font-size:17px;font-weight:800;color:${c.color||'#0f172a'};letter-spacing:-0.3px;">${c.value}</div>
      </div>`;
    });
    summaryHtml += '</div>';
  }

  let headerCols = '';
  columns.forEach(c => {
    headerCols += `<th style="text-align:${c.align||'left'};${c.color?'color:'+c.color+';':''}">${c.label}</th>`;
  });

  const reportContent = `
    <div style="max-width:210mm;margin:0 auto;padding:20px 24px;font-family:'Segoe UI',system-ui,-apple-system,sans-serif;color:#1e293b;font-size:11.5px;line-height:1.5;position:relative;">
      <div style="position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-35deg);font-size:72px;font-weight:900;color:rgba(184,134,11,0.04);letter-spacing:8px;white-space:nowrap;pointer-events:none;z-index:-1;">NASAMA PROPERTIES</div>

      <div style="display:flex;align-items:center;justify-content:space-between;padding-bottom:14px;margin-bottom:6px;border-bottom:3px solid #b8860b;">
        <img src="${COMPANY_LOGO}" alt="Nasama Properties" style="height:52px;"/>
        <div style="text-align:right;font-size:10px;color:#64748b;line-height:1.6;">
          <strong style="color:#1e293b;font-size:11px;">Nasama Properties LLC</strong><br/>
          Binghatti Emerald, Office 218, JVC, Dubai<br/>
          www.nasamaproperties.com<br/>
          <span style="display:inline-block;padding:2px 8px;background:#fef3c7;color:#92400e;font-weight:700;border-radius:3px;font-size:8px;letter-spacing:.4px;margin-top:4px;">CONFIDENTIAL</span>
        </div>
      </div>

      <div style="margin:14px 0 4px;">
        <div style="font-size:19px;font-weight:800;color:#0f172a;letter-spacing:-0.3px;margin-bottom:2px;">${title}</div>
        <div style="font-size:11px;color:#64748b;">${subtitle||''}</div>
      </div>

      <div style="display:flex;gap:0;margin:12px 0 6px;border:1px solid #e2e8f0;border-radius:6px;overflow:hidden;font-size:10px;">
        <div style="flex:1;padding:8px 14px;background:#f8fafc;border-right:1px solid #e2e8f0;color:#475569;">Report Date<strong style="color:#0f172a;display:block;margin-top:1px;">${today}</strong></div>
        ${period?'<div style="flex:1;padding:8px 14px;background:#fef3c7;border-right:1px solid #e2e8f0;color:#92400e;">Report Period<strong style="color:#0f172a;display:block;margin-top:1px;">'+period+'</strong></div>':''}
        <div style="flex:1;padding:8px 14px;background:#f8fafc;border-right:1px solid #e2e8f0;color:#475569;">Reference No.<strong style="color:#0f172a;display:block;margin-top:1px;">${ref}</strong></div>
        <div style="flex:1;padding:8px 14px;background:#f8fafc;border-right:1px solid #e2e8f0;color:#475569;">Prepared By<strong style="color:#0f172a;display:block;margin-top:1px;">HR Department</strong></div>
        <div style="flex:1;padding:8px 14px;background:#f8fafc;color:#475569;">Classification<strong style="color:#0f172a;display:block;margin-top:1px;">Confidential</strong></div>
      </div>

      ${summaryHtml}

      <table style="width:100%;border-collapse:collapse;margin-bottom:8px;border:1px solid #e2e8f0;">
        <thead><tr style="background:#f1f5f9;">${headerCols.replace(/<th /g,'<th style="font-size:9px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.5px;padding:7px 8px;border-bottom:2px solid #cbd5e1;" ').replace(/<th>/g,'<th style="font-size:9px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.5px;padding:7px 8px;border-bottom:2px solid #cbd5e1;">')}</tr></thead>
        <tbody>${tableRows}</tbody>
        ${footerHtml}
      </table>

      <div style="font-size:9px;color:#94a3b8;margin-bottom:4px;text-align:right;">
        Total records: ${rows.length} · Generated: ${today}
      </div>

      <div style="margin-top:50px;page-break-inside:avoid;border-top:1px solid #e2e8f0;padding-top:16px;">
        <div style="font-size:9px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:1px;margin-bottom:24px;">Authorization &amp; Approval</div>
        <div style="display:flex;justify-content:space-between;gap:32px;">
          <div style="flex:1;text-align:center;">
            <div style="height:56px;border-bottom:1.5px solid #334155;margin-bottom:8px;"></div>
            <div style="font-size:11px;font-weight:700;color:#0f172a;margin-bottom:1px;">HR Manager</div>
            <div style="font-size:9.5px;color:#64748b;">Human Resources Department</div>
            <div style="font-size:9px;color:#94a3b8;margin-top:4px;">Date: _______________</div>
          </div>
          <div style="flex:1;text-align:center;">
            <div style="height:56px;border-bottom:1.5px solid #334155;margin-bottom:8px;"></div>
            <div style="font-size:11px;font-weight:700;color:#0f172a;margin-bottom:1px;">Finance Director</div>
            <div style="font-size:9.5px;color:#64748b;">Finance Department</div>
            <div style="font-size:9px;color:#94a3b8;margin-top:4px;">Date: _______________</div>
          </div>
          <div style="flex:1;text-align:center;">
            <div style="height:56px;border-bottom:1.5px solid #334155;margin-bottom:8px;"></div>
            <div style="font-size:11px;font-weight:700;color:#0f172a;margin-bottom:1px;">Chief Executive Officer</div>
            <div style="font-size:9.5px;color:#64748b;">Final Approval</div>
            <div style="font-size:9px;color:#94a3b8;margin-top:4px;">Date: _______________</div>
          </div>
        </div>
        <div style="margin-top:28px;text-align:center;">
          <div style="display:inline-block;width:120px;height:120px;border:2px dashed #cbd5e1;border-radius:50%;"></div>
          <div style="font-size:8px;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;margin-top:6px;">Company Stamp</div>
        </div>
      </div>

      <div style="margin-top:24px;padding-top:10px;border-top:1.5px solid #b8860b;display:flex;justify-content:space-between;align-items:center;font-size:8.5px;color:#94a3b8;">
        <div>
          <strong style="color:#b8860b;">Nasama Properties LLC</strong> · Binghatti Emerald, Office 218, JVC, Dubai<br/>
          This document is confidential and intended solely for the authorized recipient(s).
        </div>
        <div style="text-align:right;">
          Ref: ${ref}<br/>
          Page 1 of 1
        </div>
      </div>
    </div>`;

  // Remove any existing print overlay
  let existing = document.getElementById('nasama-print-overlay');
  if(existing) existing.remove();

  // Create full-page overlay
  const overlay = document.createElement('div');
  overlay.id = 'nasama-print-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:99999;background:#fff;overflow-y:auto;';

  // Toolbar (hidden when printing)
  const toolbar = document.createElement('div');
  toolbar.className = 'report-toolbar-noprint';
  toolbar.style.cssText = 'padding:10px 20px;background:#0f172a;color:#fff;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:1;';
  toolbar.innerHTML = `
    <span style="font-weight:700;font-size:13px;">📄 Preview — ${title}</span>
    <div style="display:flex;gap:8px;">
      <button id="rpt-print-btn" style="padding:8px 24px;background:#b8860b;color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print / Save as PDF</button>
      <button id="rpt-close-btn" style="padding:8px 16px;background:transparent;color:#94a3b8;border:1px solid #475569;border-radius:6px;cursor:pointer;font-size:13px;">Close</button>
    </div>`;

  // Report content
  const content = document.createElement('div');
  content.className = 'report-content-print';
  content.innerHTML = reportContent;

  overlay.appendChild(toolbar);
  overlay.appendChild(content);
  document.body.appendChild(overlay);

  function closeOverlay() {
    overlay.remove();
  }

  document.getElementById('rpt-close-btn').onclick = closeOverlay;
  document.getElementById('rpt-print-btn').onclick = function() {
    // Hide toolbar and app, print only report
    toolbar.style.display = 'none';
    document.getElementById('root').style.display = 'none';
    overlay.style.position = 'static';
    window.print();
    // Restore after print dialog
    setTimeout(function(){
      toolbar.style.display = '';
      document.getElementById('root').style.display = '';
      overlay.style.position = 'fixed';
    }, 500);
  };

  // Close on Escape
  function escHandler(e) { if(e.key==='Escape') { closeOverlay(); document.removeEventListener('keydown', escHandler); } }
  document.addEventListener('keydown', escHandler);
}

export function generateHRLetter(type, emp, extraData) {
  const today = new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'});
  const ref = 'NP/HR/'+new Date().getFullYear()+'/'+Date.now().toString(36).toUpperCase().slice(-5);
  const joinDate = emp.joined ? new Date(emp.joined).toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'}) : '_______________';

  const TEMPLATES = {
    'Employment Certificate': {
      subject: 'TO WHOM IT MAY CONCERN',
      body: `<p>This is to certify that <strong>${emp.name}</strong>, holding <strong>${emp.nationality||'_______________'}</strong> nationality, 
      bearing Passport No. <strong>${emp.passNo||'_______________'}</strong>, has been employed with 
      <strong>Nasama Properties LLC</strong> since <strong>${joinDate}</strong> and continues to work with us 
      as <strong>${emp.title||'_______________'}</strong> in the <strong>${emp.dept||'_______________'}</strong> department.</p>
      
      <p>As of the date of this letter, ${emp.name} is a full-time employee and remains in good standing with the company.</p>
      
      <p>This certificate is issued upon the request of the above-named employee for whatever legal purpose it may serve, 
      without any responsibility on the part of the company.</p>`
    },
    'Salary Certificate': {
      subject: 'SALARY CERTIFICATE',
      body: `<p>This is to certify that <strong>${emp.name}</strong>, holding <strong>${emp.nationality||'_______________'}</strong> nationality, 
      bearing Passport No. <strong>${emp.passNo||'_______________'}</strong>, is currently employed with 
      <strong>Nasama Properties LLC</strong> since <strong>${joinDate}</strong> and is designated as 
      <strong>${emp.title||'_______________'}</strong> in the <strong>${emp.dept||'_______________'}</strong> department.</p>
      
      <p>The details of the monthly compensation are as follows:</p>
      
      <table style="width:80%;margin:16px 0;border-collapse:collapse;">
        <tr style="background:#f8fafc;"><td style="padding:8px 14px;border:1px solid #e2e8f0;font-weight:600;">Basic Salary</td><td style="padding:8px 14px;border:1px solid #e2e8f0;text-align:right;font-weight:700;">AED ${(emp.salary||0).toLocaleString()}</td></tr>
        ${(emp.housing||0)>0?'<tr><td style="padding:8px 14px;border:1px solid #e2e8f0;">SIM Card Allow</td><td style="padding:8px 14px;border:1px solid #e2e8f0;text-align:right;font-weight:700;">AED '+(emp.housing).toLocaleString()+'</td></tr>':''}
        ${(emp.transport||0)>0?'<tr><td style="padding:8px 14px;border:1px solid #e2e8f0;">Transport Allowance</td><td style="padding:8px 14px;border:1px solid #e2e8f0;text-align:right;font-weight:700;">AED '+(emp.transport).toLocaleString()+'</td></tr>':''}
        <tr style="background:#f1f5f9;"><td style="padding:8px 14px;border:1px solid #cbd5e1;font-weight:800;">Total Monthly Salary</td><td style="padding:8px 14px;border:1px solid #cbd5e1;text-align:right;font-weight:800;font-size:15px;">AED ${((emp.salary||0)+(emp.housing||0)+(emp.transport||0)).toLocaleString()}</td></tr>
      </table>
      
      <p>This certificate is issued upon the request of the above-named employee for whatever legal purpose it may serve, 
      without any responsibility on the part of the company.</p>`
    },
    'NOC Letter': {
      subject: 'NO OBJECTION CERTIFICATE',
      body: `<p>This is to certify that <strong>${emp.name}</strong>, holding <strong>${emp.nationality||'_______________'}</strong> nationality, 
      bearing Passport No. <strong>${emp.passNo||'_______________'}</strong>, is employed with 
      <strong>Nasama Properties LLC</strong> since <strong>${joinDate}</strong> as 
      <strong>${emp.title||'_______________'}</strong> in the <strong>${emp.dept||'_______________'}</strong> department.</p>
      
      <p>We have <strong>No Objection</strong> for the above-named employee to:</p>
      
      <div style="margin:12px 0 16px;padding:14px 18px;background:#f8fafc;border-left:4px solid #b8860b;border-radius:0 6px 6px 0;font-size:13px;color:#334155;">
        ${extraData?.reason||'[Purpose as stated in the request]'}
      </div>
      
      <p>This No Objection Certificate is valid for a period of <strong>30 days</strong> from the date of issuance.</p>
      
      <p>This certificate is issued upon the request of the above-named employee without any responsibility on the part of the company.</p>`
    },
    'Experience Certificate': {
      subject: 'EXPERIENCE CERTIFICATE',
      body: `<p>This is to certify that <strong>${emp.name}</strong>, holding <strong>${emp.nationality||'_______________'}</strong> nationality, 
      bearing Passport No. <strong>${emp.passNo||'_______________'}</strong>, was employed with 
      <strong>Nasama Properties LLC</strong> from <strong>${joinDate}</strong> to <strong>${emp.contractEnd?new Date(emp.contractEnd).toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'}):'_______________'}</strong>.</p>
      
      <p>During the period of employment, ${emp.name} held the position of <strong>${emp.title||'_______________'}</strong> in the 
      <strong>${emp.dept||'_______________'}</strong> department and was responsible for the duties associated with the said position.</p>
      
      <p>During the tenure with us, we found ${emp.name} to be a dedicated, reliable, and hardworking professional. 
      ${emp.name} maintained a high standard of work and demonstrated excellent professional conduct throughout the employment period.</p>
      
      <p>We wish ${emp.name} all the best in future endeavors.</p>
      
      <p>This certificate is issued upon request for whatever legal purpose it may serve.</p>`
    },
  };

  const tpl = TEMPLATES[type];
  if(!tpl) return alert('No template available for this request type. Templates are available for: Employment Certificate, Salary Certificate, NOC Letter, Experience Certificate.');

  const letterHtml = `
    <div style="max-width:210mm;margin:0 auto;padding:28px 32px;font-family:'Segoe UI',system-ui,-apple-system,sans-serif;color:#1e293b;font-size:13px;line-height:1.7;">
      
      <!-- Letterhead -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding-bottom:16px;border-bottom:3px solid #b8860b;margin-bottom:24px;">
        <img src="${COMPANY_LOGO}" alt="Nasama Properties" style="height:56px;"/>
        <div style="text-align:right;font-size:10px;color:#64748b;line-height:1.6;">
          <strong style="color:#1e293b;font-size:11px;">Nasama Properties LLC</strong><br/>
          Binghatti Emerald, Office 218, JVC, Dubai<br/>
          United Arab Emirates<br/>
          www.nasamaproperties.com
        </div>
      </div>

      <!-- Date & Reference -->
      <div style="display:flex;justify-content:space-between;margin-bottom:28px;font-size:12px;color:#475569;">
        <div>
          <div>Date: <strong>${today}</strong></div>
          <div>Ref: <strong>${ref}</strong></div>
        </div>
      </div>

      <!-- Subject -->
      <div style="text-align:center;margin-bottom:28px;">
        <div style="font-size:16px;font-weight:800;color:#0f172a;letter-spacing:1px;text-decoration:underline;text-underline-offset:6px;">${tpl.subject}</div>
      </div>

      <!-- Body -->
      <div style="font-size:13px;line-height:1.8;color:#1e293b;">
        ${tpl.body}
      </div>

      <!-- Closing -->
      <div style="margin-top:32px;font-size:13px;">
        <p>Should you require any further information or clarification, please do not hesitate to contact us.</p>
        <p style="margin-top:8px;">Yours faithfully,</p>
      </div>

      <!-- Signature blocks -->
      <div style="margin-top:50px;display:flex;justify-content:space-between;gap:40px;page-break-inside:avoid;">
        <div style="flex:1;">
          <div style="height:50px;border-bottom:1.5px solid #334155;margin-bottom:8px;"></div>
          <div style="font-size:12px;font-weight:700;color:#0f172a;">Authorized Signatory</div>
          <div style="font-size:11px;color:#64748b;">HR Department</div>
          <div style="font-size:11px;color:#64748b;">Nasama Properties LLC</div>
        </div>
        <div style="flex:1;text-align:center;">
          <div style="display:inline-block;width:100px;height:100px;border:2px dashed #cbd5e1;border-radius:50%;margin-bottom:6px;"></div>
          <div style="font-size:9px;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;">Company Stamp</div>
        </div>
      </div>

      <!-- Footer -->
      <div style="margin-top:40px;padding-top:10px;border-top:1.5px solid #b8860b;font-size:8.5px;color:#94a3b8;display:flex;justify-content:space-between;">
        <div><strong style="color:#b8860b;">Nasama Properties LLC</strong> · Binghatti Emerald, Office 218, JVC, Dubai · www.nasamaproperties.com</div>
        <div>Ref: ${ref}</div>
      </div>
    </div>`;

  // Show in overlay
  let existing = document.getElementById('nasama-print-overlay');
  if(existing) existing.remove();

  const overlay = document.createElement('div');
  overlay.id = 'nasama-print-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:99999;background:#fff;overflow-y:auto;';

  const toolbar = document.createElement('div');
  toolbar.className = 'report-toolbar-noprint';
  toolbar.style.cssText = 'padding:10px 20px;background:#0f172a;color:#fff;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:1;';
  toolbar.innerHTML = `
    <span style="font-weight:700;font-size:13px;">📄 ${type} — ${emp.name}</span>
    <div style="display:flex;gap:8px;">
      <button id="ltr-print-btn" style="padding:8px 24px;background:#b8860b;color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print / Save as PDF</button>
      <button id="ltr-close-btn" style="padding:8px 16px;background:transparent;color:#94a3b8;border:1px solid #475569;border-radius:6px;cursor:pointer;font-size:13px;">Close</button>
    </div>`;

  const content = document.createElement('div');
  content.className = 'report-content-print';
  content.style.cssText = 'background:#fff;';
  content.innerHTML = letterHtml;

  overlay.appendChild(toolbar);
  overlay.appendChild(content);
  document.body.appendChild(overlay);

  function closeOverlay() { overlay.remove(); }
  document.getElementById('ltr-close-btn').onclick = closeOverlay;
  document.getElementById('ltr-print-btn').onclick = function() {
    toolbar.style.display = 'none';
    document.getElementById('root').style.display = 'none';
    overlay.style.position = 'static';
    window.print();
    setTimeout(function(){
      toolbar.style.display = '';
      document.getElementById('root').style.display = '';
      overlay.style.position = 'fixed';
    }, 500);
  };
  function escHandler(e) { if(e.key==='Escape') { closeOverlay(); document.removeEventListener('keydown', escHandler); } }
  document.addEventListener('keydown', escHandler);
}